  "inlineSchema": "// DateNight — Prisma schema\n// Users, groups, invitations, date proposals, activity options, votes.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel User {\n  id           String    @id @default(uuid())\n  email        String    @unique\n  passwordHash String?\n  displayName  String\n  // OAuth provider fields\n  provider     String? // 'google' | 'apple' | 'facebook' | 'linkedin' | 'microsoft'\n  providerId   String? // provider's user ID\n  avatarUrl    String?\n  pushToken    String? // Expo push notification token\n  // Optional home location for recommendations\n  latitude     Float?\n  longitude    Float?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n  // GDPR: soft-delete marker; hard delete via scheduled job within 30 days\n  deletedAt    DateTime?\n\n  memberships     GroupMember[]\n  sentInvitations Invitation[]  @relation(\"Inviter\")\n  proposals       Proposal[]\n  votes           Vote[]\n\n  @@unique([provider, providerId])\n}\n\nmodel Group {\n  id          String   @id @default(uuid())\n  name        String\n  description String?\n  groupType   String? // 'COUPLE' | 'FRIENDS' | 'FAMILY'\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  members     GroupMember[]\n  invitations Invitation[]\n  proposals   Proposal[]\n}\n\nmodel GroupMember {\n  id       String   @id @default(uuid())\n  groupId  String\n  userId   String\n  role     Role     @default(MEMBER)\n  joinedAt DateTime @default(now())\n\n  group Group @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  user  User  @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([groupId, userId])\n  @@index([userId])\n}\n\nenum Role {\n  OWNER\n  MEMBER\n}\n\n// Invitation methods: LINK, EMAIL, SMS, QR, USERNAME (5 methods per spec)\nenum InviteMethod {\n  LINK\n  EMAIL\n  SMS\n  QR\n  USERNAME\n}\n\nenum InviteStatus {\n  PENDING\n  ACCEPTED\n  DECLINED\n  EXPIRED\n}\n\nmodel Invitation {\n  id        String       @id @default(uuid())\n  groupId   String\n  inviterId String\n  method    InviteMethod\n  // token used in invite links / QR codes\n  token     String       @unique @default(uuid())\n  // target contact for EMAIL/SMS/USERNAME methods\n  target    String?\n  status    InviteStatus @default(PENDING)\n  expiresAt DateTime\n  createdAt DateTime     @default(now())\n\n  group   Group @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  inviter User  @relation(\"Inviter\", fields: [inviterId], references: [id], onDelete: Cascade)\n}\n\nenum ProposalStatus {\n  OPEN\n  COUNTERED\n  DECIDED\n  CANCELLED\n}\n\nmodel Proposal {\n  id        String         @id @default(uuid())\n  groupId   String\n  creatorId String\n  title     String\n  // proposed date/time of the outing\n  dateTime  DateTime\n  status    ProposalStatus @default(OPEN)\n  // if this proposal is a counter-proposal, link to the original\n  parentId  String?\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  group    Group      @relation(fields: [groupId], references: [id], onDelete: Cascade)\n  creator  User       @relation(fields: [creatorId], references: [id], onDelete: Cascade)\n  parent   Proposal?  @relation(\"CounterProposals\", fields: [parentId], references: [id])\n  counters Proposal[] @relation(\"CounterProposals\")\n  options  Option[]\n\n  @@index([groupId])\n}\n\nmodel Option {\n  id          String   @id @default(uuid())\n  proposalId  String\n  name        String\n  category    String // e.g. restaurant, movie, activity, outdoors\n  description String?\n  address     String?\n  latitude    Float?\n  longitude   Float?\n  // external reference (Yelp/TMDB/Google Place id) when sourced from an API\n  externalRef String?\n  createdAt   DateTime @default(now())\n\n  proposal Proposal @relation(fields: [proposalId], references: [id], onDelete: Cascade)\n  votes    Vote[]\n}\n\nmodel Vote {\n  id        String   @id @default(uuid())\n  optionId  String\n  userId    String\n  // simple approval voting: a vote row = approval\n  createdAt DateTime @default(now())\n\n  option Option @relation(fields: [optionId], references: [id], onDelete: Cascade)\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([optionId, userId])\n  @@index([optionId])\n}\n",
